-- 一次性迁移模板：先运行对应 inventory，备份并审阅表名、映射及冲突。
-- 默认最终 ROLLBACK；正式执行须明确改为 COMMIT。不要使用客户端忽略错误选项。
-- 仅 language_lines.text 的语言键；不改 group/key，不作为运行时兼容层。
START TRANSACTION;
SELECT * FROM language_lines FOR UPDATE;
CREATE TEMPORARY TABLE openrust_locale_guard (valid INTEGER NOT NULL CHECK (valid = 1));
-- 冲突或未知旧键会触发约束失败，必须回滚整个事务，禁止覆盖两份内容。
INSERT INTO openrust_locale_guard SELECT CASE WHEN EXISTS (SELECT 1 FROM language_lines WHERE ((JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') AND JSON_CONTAINS_PATH(`text`, 'one', '$."zh-Hans"')) OR (JSON_CONTAINS_PATH(`text`, 'one', '$."zh_TW"') AND JSON_CONTAINS_PATH(`text`, 'one', '$."zh-Hant"')) OR (JSON_CONTAINS_PATH(`text`, 'one', '$."en_US"') AND JSON_CONTAINS_PATH(`text`, 'one', '$."en-US"')) OR (JSON_CONTAINS_PATH(`text`, 'one', '$."en_GB"') AND JSON_CONTAINS_PATH(`text`, 'one', '$."en-GB"'))) OR (EXISTS (SELECT 1 FROM JSON_TABLE(JSON_KEYS(`text`), '$[*]' COLUMNS(tag VARCHAR(255) PATH '$')) AS tags WHERE LOCATE('_', tag) > 0 AND tag NOT IN ('zh_CN', 'zh_TW', 'en_US', 'en_GB')))) THEN 0 ELSE 1 END;
UPDATE language_lines SET `text` = CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."en_GB"') THEN JSON_REMOVE(JSON_SET(CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."en_US"') THEN JSON_REMOVE(JSON_SET(CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_TW"') THEN JSON_REMOVE(JSON_SET(CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END, '$."zh-Hant"', JSON_EXTRACT(`text`, '$."zh_TW"')), '$."zh_TW"') ELSE CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END END, '$."en-US"', JSON_EXTRACT(`text`, '$."en_US"')), '$."en_US"') ELSE CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_TW"') THEN JSON_REMOVE(JSON_SET(CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END, '$."zh-Hant"', JSON_EXTRACT(`text`, '$."zh_TW"')), '$."zh_TW"') ELSE CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END END END, '$."en-GB"', JSON_EXTRACT(`text`, '$."en_GB"')), '$."en_GB"') ELSE CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."en_US"') THEN JSON_REMOVE(JSON_SET(CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_TW"') THEN JSON_REMOVE(JSON_SET(CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END, '$."zh-Hant"', JSON_EXTRACT(`text`, '$."zh_TW"')), '$."zh_TW"') ELSE CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END END, '$."en-US"', JSON_EXTRACT(`text`, '$."en_US"')), '$."en_US"') ELSE CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_TW"') THEN JSON_REMOVE(JSON_SET(CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END, '$."zh-Hant"', JSON_EXTRACT(`text`, '$."zh_TW"')), '$."zh_TW"') ELSE CASE WHEN JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') THEN JSON_REMOVE(JSON_SET(`text`, '$."zh-Hans"', JSON_EXTRACT(`text`, '$."zh_CN"')), '$."zh_CN"') ELSE `text` END END END END
WHERE JSON_CONTAINS_PATH(`text`, 'one', '$."zh_CN"') OR JSON_CONTAINS_PATH(`text`, 'one', '$."zh_TW"') OR JSON_CONTAINS_PATH(`text`, 'one', '$."en_US"') OR JSON_CONTAINS_PATH(`text`, 'one', '$."en_GB"');
DROP TEMPORARY TABLE openrust_locale_guard;
ROLLBACK;
